def luminance(h):
 v=[int(h[i:i+2],16)/255 for i in (1,3,5)];v=[c/12.92 if c<=.04045 else ((c+.055)/1.055)**2.4 for c in v];return sum(c*w for c,w in zip(v,[.2126,.7152,.0722]))
def contrast(a,b):
 x,y=sorted([luminance(a),luminance(b)]);return (y+.05)/(x+.05)
contrasts={}
for i,p in enumerate(portfolio,1):
 c=dict(zip(['canvas','surface','surface2','text','muted','border','action','label'],p['palette']))
 c.update(link=c['action'],focus='#005FCC',error='#B42318',errorSurface='#FFF4F2',warning='#7A3E00',warningSurface='#FFF4CE',success='#166534',successSurface='#EDF8EF')
 pairs=[('main text / canvas','text','canvas',4.5),('supporting / canvas','muted','canvas',4.5),('label / action','label','action',4.5),('link / surface','link','surface',4.5),('control border / surface','border','surface',3),('focus / surface','focus','surface',3),('error / error surface','error','errorSurface',4.5),('warning / warning surface','warning','warningSurface',4.5),('success / success surface','success','successSurface',4.5),('supporting / surface2','muted','surface2',4.5)]
 contrasts[p['id']]=[dict(pair=n,foreground=c[a],background=c[b],ratio=round(contrast(c[a],c[b]),2),threshold=threshold,passes=contrast(c[a],c[b])>=threshold) for n,a,b,threshold in pairs]
 palette='| Role | Exact proposed value / pairing |\n|---|---|\n'+''.join(f'| {k} | `{v}` |\n' for k,v in c.items())
 palette+=f'| Secondary action | transparent on surface; `{c["action"]}` text and border |\n| Selected | `{c["action"]}` fill / `{c["label"]}` label plus check and selected text |\n| Promotional | `{c["surface2"]}` / `{c["text"]}`; no manufactured urgency |\n| Disabled | surface2 with muted text; labelled unavailable and programmatic disabled state |\n'
 ratio='| Pair | Ratio | Criterion used | Result |\n|---|---:|---:|---|\n'+''.join(f'| {r["pair"]} | {r["ratio"]}:1 | {r["threshold"]}:1 | {"pass" if r["passes"] else "revise"} |\n' for r in contrasts[p['id']])
 transition='Stable ID retained; proposal is a new, explicitly selected design version, never a silent rewrite of existing installations.'
